package org.humanjourney.core.progress;
import java.util.*;
import com.google.gson.*;
/** Sanitised snapshot: no server references, hidden node identities, conditions or raw graph JSON. */
public record ProgressView(int version,boolean participant,String title,String message,List<ProgressGraph.Era> eras,List<Node> nodes,List<ProgressGraph.Edge> connections) {
 public enum State {LOCKED,AVAILABLE,COMPLETED}
 public record Requirement(String label,boolean completed,boolean revealed){public Requirement{validText(label,128);}}
 public record Node(String id,String era,String title,String description,String icon,double x,double y,ProgressGraph.Category category,State state,boolean known,Integer current,Integer targetMin,Integer targetMax,List<Requirement> requires,boolean gatePassed,boolean placeholder){public Node{validText(id,96);validText(era,96);validText(title,128);validText(description,2048);validText(icon,128);if(!icon.matches("[a-z0-9_.-]+:[a-z0-9_./-]+")||!Double.isFinite(x)||!Double.isFinite(y)||Math.abs(x)>100000||Math.abs(y)>100000||category==null||state==null||requires==null||requires.size()>32)throw new IllegalArgumentException("invalid node view");requires=List.copyOf(requires);}}
 static void validText(String s,int max){if(s==null||s.length()>max)throw new IllegalArgumentException("invalid bounded progress text");}
 public ProgressView{if(version!=1||eras==null||nodes==null||connections==null||eras.size()>ProgressGraph.MAX_ERAS||nodes.size()>ProgressGraph.MAX_NODES||connections.size()>ProgressGraph.MAX_EDGES)throw new IllegalArgumentException("invalid progress snapshot bounds");validText(title,128);validText(message,512);eras=List.copyOf(eras);nodes=List.copyOf(nodes);connections=List.copyOf(connections);var eraIds=new HashSet<String>();for(var e:eras){if(e==null||e.visibleWhen()==null||!e.visibleWhen().isEmpty()||!eraIds.add(e.id())||!Double.isFinite(e.start())||!Double.isFinite(e.end())||e.start()>=e.end()||Math.abs(e.start())>100000||Math.abs(e.end())>100000)throw new IllegalArgumentException("invalid sanitised Era");validText(e.id(),96);validText(e.title(),128);}var ids=new HashSet<String>();for(var n:nodes)if(n==null||!ids.add(n.id())||!eraIds.contains(n.era()))throw new IllegalArgumentException("invalid projected node identity");for(var e:connections){if(e==null||e.kind()==null||e.route()==null||e.route().size()>16||!ids.contains(e.from())||!ids.contains(e.to()))throw new IllegalArgumentException("invalid projected connection");for(var p:e.route())if(p==null||!Double.isFinite(p.x())||!Double.isFinite(p.y())||Math.abs(p.x())>100000||Math.abs(p.y())>100000)throw new IllegalArgumentException("invalid route");}if(!participant&&(!nodes.isEmpty()||!eras.isEmpty()||!connections.isEmpty()))throw new IllegalArgumentException("non-participant graph leak");}
 public static ProgressView empty(boolean participant){return new ProgressView(1,participant,"Civilization Progress",participant?"This server has no civilization graph configured.":"Available to Human Journey participants.",List.of(),List.of(),List.of());}
 public String json(){return new Gson().toJson(this);}
 /** Conservative all-revealed UTF-8 envelope, even for mutually exclusive visibility rules. */
 public static void checkCapacity(ProgressGraph graph){var source=graph.nodeMap();var nodes=new ArrayList<Node>();for(var n:graph.nodes()){var req=new ArrayList<Requirement>();for(String id:n.requires())req.add(new Requirement(source.get(id).title().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>=22?source.get(id).title():"Unrevealed prerequisite",false,false));nodes.add(new Node(n.id(),n.era(),n.title(),n.description(),n.icon(),n.x(),n.y(),n.category(),State.COMPLETED,false,Integer.MIN_VALUE,n.completion().type().equals("score")?n.completion().min():Integer.MIN_VALUE,n.completion().type().equals("score")?n.completion().max():Integer.MAX_VALUE,req,false,n.placeholder()));}var eras=graph.eras().stream().map(e->new ProgressGraph.Era(e.id(),e.title(),e.color(),e.background(),e.start(),e.end(),e.order(),List.of())).toList();if(new ProgressView(1,true,graph.title(),"",eras,nodes,graph.connections()).json().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>ProgressPackets.MAX_SNAPSHOT)throw new IllegalArgumentException("graph exceeds2MiB worst-case sanitised snapshot; reduce content/repetition");}
 public static ProgressView parse(String json){ProgressJson.bounded(json,ProgressPackets.MAX_SNAPSHOT);var view=new Gson().fromJson(json,ProgressView.class);if(view==null)throw new IllegalArgumentException("empty view");return view;}
 public static ProgressView project(ProgressGraph graph,ProgressGraph.Scores scores){if(graph.nodes().isEmpty())return empty(true);var values=new HashMap<String,OptionalInt>();ProgressGraph.Scores cached=(o,h)->values.computeIfAbsent(o+"\u0000"+h,k->scores.read(o,h));var source=graph.nodeMap();var visibleEras=new HashSet<String>();for(var e:graph.eras())if(ProgressGraph.all(e.visibleWhen(),cached))visibleEras.add(e.id());var visible=new HashSet<String>();for(var n:graph.nodes())if(visibleEras.contains(n.era())&&ProgressGraph.all(n.visibleWhen(),cached))visible.add(n.id());var out=new ArrayList<Node>();for(var n:graph.nodes()){if(!visible.contains(n.id()))continue;var reqs=new ArrayList<Requirement>();boolean ready=true;for(String id:n.requires()){var p=source.get(id);boolean complete=p.completion().test(cached);ready&=complete;boolean revealed=visible.contains(id);reqs.add(new Requirement(revealed?p.title():"Unrevealed prerequisite",revealed&&complete,revealed));}var value=n.completion().value(cached);boolean known=!n.completion().type().equals("score")||value.isPresent();boolean gate=ProgressGraph.all(n.availableWhen(),cached);var state=n.completion().test(cached)?State.COMPLETED:known&&ready&&gate?State.AVAILABLE:State.LOCKED;out.add(new Node(n.id(),n.era(),n.title(),n.description(),n.icon(),n.x(),n.y(),n.category(),state,known,value.isPresent()?value.getAsInt():null,n.completion().type().equals("score")?n.completion().min():null,n.completion().type().equals("score")?n.completion().max():null,reqs,gate,n.placeholder()));}var used=new HashSet<String>();for(var n:out)used.add(n.era());var eras=new ArrayList<ProgressGraph.Era>();for(var e:graph.eras())if(used.contains(e.id()))eras.add(new ProgressGraph.Era(e.id(),e.title(),e.color(),e.background(),e.start(),e.end(),e.order(),List.of()));var edges=graph.connections().stream().filter(e->visible.contains(e.from())&&visible.contains(e.to())).toList();return new ProgressView(1,true,graph.title(),out.isEmpty()?"No progress content is currently revealed.":"",eras,out,edges);}
}
